{
  "correction_rules": [
    "Bias correction: Model consistently underestimates prices in early 30-day forecasts; adjust downward by 0.5–1.5% for first 5 days.",
    "Lag correction: Forecast often lags true price movements by 2–4 days; apply a 1-day forward shift for short-term (1–7 day) price alignment.",
    "Overshoot after spikes: After price spikes (e.g., >65), model overcorrects downward; reduce forecast amplitude by 10–15% in subsequent 3–5 days.",
    "Mean reversion: If price deviates >3σ from 30-day moving average, apply mean-reversion pullback of 0.5–1.0% per day until convergence.",
    "Sentiment sensitivity: If sentiment history is 0.00 (neutral), apply no adjustment; if sentiment >0.3, increase forecast by 0.5–1.0%; if sentiment < -0.3, decrease by 0.5–1.0%."
  ]
}
